// Data access for the wbs-queries.ts module. Every query and write its screens make
// goes through here; components do not call the database directly.
//
// Each function returns the Supabase query itself, so callers await it (or call
// .then) and read `{ data, error }` as usual. Functions are grouped by table.
//
// Generated by scripts/codemods/extract-service.mjs and then maintained by hand.
// Keep the "// @table" markers: the codemod reads them when it is run again.

import { createClient } from "@/lib/supabase/client";

const db = () => createClient();

// ── clone_wbs_template_to_project ─────────────────────────────────────────────

// @table clone_wbs_template_to_project
export function cloneWbsTemplateToProject(args: object) {
  return db().rpc("clone_wbs_template_to_project", args);
}

// ── close_weekly_plan ─────────────────────────────────────────────────────────

// @table close_weekly_plan
export function closeWeeklyPlan(args: object) {
  return db().rpc("close_weekly_plan", args);
}

// ── departments ───────────────────────────────────────────────────────────────

// @table departments
export function getDepartmentById(id: string | number | boolean) {
  return db().from("departments").select("department_head").eq("id", id).maybeSingle();
}

// @table departments
export function listDepartments() {
  return db().from("departments").select("id, department_code, department_name").order("department_name");
}

// ── generate_wbs_from_master_library_items ────────────────────────────────────

// @table generate_wbs_from_master_library_items
export function generateWbsFromMasterLibraryItems(args: object) {
  return db().rpc("generate_wbs_from_master_library_items", args);
}

// ── import_master_wbs ─────────────────────────────────────────────────────────

// @table import_master_wbs
export function importMasterWbs(args: object) {
  return db().rpc("import_master_wbs", args);
}

// ── profiles ──────────────────────────────────────────────────────────────────

// @table profiles
export function getProfileById(id: string | number | boolean, columns: string) {
  return db().from("profiles").select(columns as "*").eq("id", id).maybeSingle();
}

// @table profiles
export function getProfileByIdOfRole(id: string | number | boolean) {
  return db().from("profiles").select("role").eq("id", id).single();
}

// @table profiles
export function listProfiles() {
  return db().from("profiles").select("id, full_name, role, avatar_url, department").order("full_name");
}

// @table profiles
export function listProfilesOfIdAndFullName() {
  return db().from("profiles").select("id, full_name");
}

// ── task_constraints ──────────────────────────────────────────────────────────

// @table task_constraints
export function listTaskConstraintsByTaskIds(taskIds: readonly (string | number)[]) {
  return db()
    .from("task_constraints")
    .select("task_id, constraint_type, status, source, notes")
    .in("task_id", taskIds);
}

// @table task_constraints
export function upsertTaskConstraint(row: object) {
  return db().from("task_constraints").upsert([row], { onConflict: "task_id,constraint_type" });
}

// ── task_recurrences ──────────────────────────────────────────────────────────

// @table task_recurrences
export function insertTaskRecurrence(row: object) {
  return db().from("task_recurrences").insert([row]);
}

// ── wbs_audit_log ─────────────────────────────────────────────────────────────

// @table wbs_audit_log
export function insertWbsAuditLog(row: object) {
  return db().from("wbs_audit_log").insert([row]);
}

// @table wbs_audit_log
export function insertWbsAuditLogReturning(row: object) {
  return db().from("wbs_audit_log").insert([row]).select("id").single();
}

// @table wbs_audit_log
export function listWbsAuditLogByProjectIdWithActionProgressUpdatedApprovedRejected(projectId: string | number | boolean) {
  return db()
    .from("wbs_audit_log")
    .select("wbs_task_id, action, created_at")
    .eq("project_id", projectId)
    .in("action", ["Progress Updated", "Approved", "Rejected"])
    .order("created_at", { ascending: true });
}

// @table wbs_audit_log
export function listWbsAuditLogByProjectIdWithFieldNameOwnerName(projectId: string | number | boolean) {
  return db()
    .from("wbs_audit_log")
    .select("*")
    .eq("project_id", projectId)
    .eq("field_name", "owner_name")
    .order("created_at", { ascending: false });
}

// @table wbs_audit_log
export function listWbsAuditLogByWbsTaskId(wbsTaskId: string | number | boolean) {
  return db()
    .from("wbs_audit_log")
    .select("*")
    .eq("wbs_task_id", wbsTaskId)
    .order("created_at", { ascending: false });
}

// ── wbs_node_quantities ───────────────────────────────────────────────────────

// @table wbs_node_quantities
export function listWbsNodeQuantitiesByWbsNodeIds(wbsNodeIds: readonly (string | number)[]) {
  return db().from("wbs_node_quantities").select("wbs_node_id, value").in("wbs_node_id", wbsNodeIds);
}

// @table wbs_node_quantities
export function listWbsNodeQuantitiesByWbsNodeIdsWithMetricCodeGFA(wbsNodeIds: readonly (string | number)[]) {
  return db()
    .from("wbs_node_quantities")
    .select("wbs_node_id, value")
    .eq("metric_code", "GFA")
    .in("wbs_node_id", wbsNodeIds);
}

