// @table wbs_tasks
export function insertWbsTask(row: object) {
  return db().from("wbs_tasks").insert([row]);
}

// @table wbs_tasks
export function insertWbsTasksReturning(rows: object | object[]) {
  return db().from("wbs_tasks").insert(rows).select("id").single();
}

// @table wbs_tasks
export function listWbsTasksByProjectId(projectId: string | number | boolean, columns: string) {
  return db().from("wbs_tasks").select(columns as "*").eq("project_id", projectId);
}

// @table wbs_tasks
export function listWbsTasksByProjectIdAndExceptId(projectId: string | number | boolean, exceptId: string | number | boolean) {
  return db()
    .from("wbs_tasks")
    .select("id, task_code, task_name")
    .eq("project_id", projectId)
    .neq("id", exceptId)
    .order("task_code")
    .limit(200);
}

// @table wbs_tasks
export function listWbsTasksByProjectIdOrderedBySortOrder(projectId: string | number | boolean) {
  return db()
    .from("wbs_tasks")
    .select("*")
    .eq("project_id", projectId)
    .order("sort_order", { ascending: true, nullsFirst: false });
}

// @table wbs_tasks
export function listWbsTasksByProjectIdOrderedByTaskCode(projectId: string | number | boolean) {
  return db()
    .from("wbs_tasks")
    .select("id, task_code, task_name, owner_name, progress, status")
    .eq("project_id", projectId)
    .not("status", "in", "(closed,completed,cancelled)")
    .order("task_code")
    .limit(500);
}

// @table wbs_tasks
export function updateWbsTaskById(patch: object, id: string | number | boolean) {
  return db().from("wbs_tasks").update(patch).eq("id", id);
}

